// Aseguramos que todo sean números (Floats)
msg.payload = [
    {
            temperature: parseFloat(msg.payload.temperature),
                    humidity: parseFloat(msg.payload.humidity),
                            pressure: parseFloat(msg.payload.pressure),
                                    iaq: parseFloat(msg.payload.iaq),
                                            iaq_accuracy: parseFloat(msg.payload.iaqAccuracy),
                                                    gas_resistance: parseFloat(msg.payload.gasResistance)
                                                        },
                                                            {
                                                                    location: msg.payload.location || "unknown",
                                                                            device_id: msg.payload.device_id || "unknown"
                                                                                }
                                                                                ];

                                                                                // Nombre de la tabla (Measurement)
                                                                                msg.measurement = "clima";

                                                                                return msg

// El payload ya viene listo desde el nodo anterior.
// Solo lo pasamos tal cual.
return msg;

// Recuperamos la API Key que viene DENTRO del mensaje del ESP32
var dynamicKey = msg.payload.ts_api_key;

// Validación de seguridad: Si no trae llave, no enviamos
if (!dynamicKey || dynamicKey === "") {
    node.warn("⚠️ Mensaje sin API Key de ThingSpeak. Ignorando.");
    return null; 
}

// Mapeo para ThingSpeak
msg.payload = {
    api_key: dynamicKey, // <--- Usamos la variable dinámica
    field1: msg.payload.temperature,
    field2: msg.payload.humidity,
    field3: msg.payload.iaq,
    field4: msg.payload.iaqAccuracy
    // Agrega más fields si quieres
};

return msg;

// Inicializar contadores si no existen
// Usamos 'flow' directamente (variable nativa de Node-RED)
var count = flow.get('count') || 0;

// Variables para Promedios (Floats)
var s_temp = flow.get('s_temp') || 0;
var s_hum = flow.get('s_hum') || 0;
var s_press = flow.get('s_press') || 0;
var s_iaq = flow.get('s_iaq') || 0;
var s_static = flow.get('s_static') || 0;
var s_co2 = flow.get('s_co2') || 0;
var s_voc = flow.get('s_voc') || 0;
var s_gas = flow.get('s_gas') || 0;     // Resistencia
var s_gasP = flow.get('s_gasP') || 0;   // Porcentaje
var s_rawT = flow.get('s_rawT') || 0;
var s_rawH = flow.get('s_rawH') || 0;

// Validación básica
if (msg.payload && (msg.payload.temperature !== undefined)) {

    // Acumular valores flotantes (Sumas)
    // Convertimos a Float para asegurar que sea suma matemática y no concatenación de texto
    s_temp += parseFloat(msg.payload.temperature);
    s_hum += parseFloat(msg.payload.humidity);
    s_press += parseFloat(msg.payload.pressure);
    s_iaq += parseFloat(msg.payload.iaq);
    s_static += parseFloat(msg.payload.staticIaq);
    s_co2 += parseFloat(msg.payload.co2Equivalent);
    s_voc += parseFloat(msg.payload.breathVocEquivalent);
    s_gas += parseFloat(msg.payload.gasResistance);
    s_gasP += parseFloat(msg.payload.gasPercentage);
    s_rawT += parseFloat(msg.payload.rawTemperature);
    s_rawH += parseFloat(msg.payload.rawHumidity);

    count++;

    // Guardar acumulados en el contexto de Flujo
    flow.set('count', count);
    flow.set('s_temp', s_temp);
    flow.set('s_hum', s_hum);
    flow.set('s_press', s_press);
    flow.set('s_iaq', s_iaq);
    flow.set('s_static', s_static);
    flow.set('s_co2', s_co2);
    flow.set('s_voc', s_voc);
    flow.set('s_gas', s_gas);
    flow.set('s_gasP', s_gasP);
    flow.set('s_rawT', s_rawT);
    flow.set('s_rawH', s_rawH);

    // --- MANEJO DE ENTEROS (Status) ---
    // Estrategia: "Último Valor Conocido"
    flow.set('last_acc', msg.payload.iaqAccuracy);
    flow.set('last_stab', msg.payload.stabStatus);
    flow.set('last_run', msg.payload.runInStatus);

    // Metadatos
    flow.set('lastLocation', msg.payload.location);
}

return null;

var date = new Date();
var minutes = date.getMinutes();

// Cambia 'minutes === 0' por 'true' para probar YA si quieres
if (minutes === 0) { 

    var count = flow.get('count') || 0;

    // Evitar división por cero si no hay datos
    if (count === 0) return null;

    // Función auxiliar para formatear (2 decimales)
    function fmt(val) { return (val / count).toFixed(2); }

    // Preparar el Payload Completo para Google Sheets
    // Recuperamos los datos acumulados usando 'flow.get'
    msg.payload = {
        // --- Metadatos ---
        fechaHora: new Date().toISOString().replace('T', ' ').substring(0, 19),
        location: flow.get('lastLocation'),

        // --- Promedios (Floats) ---
        temperature: fmt(flow.get('s_temp')),
        humidity: fmt(flow.get('s_hum')),
        pressure: fmt(flow.get('s_press')),
        iaq: fmt(flow.get('s_iaq')),

        staticIaq: fmt(flow.get('s_static')),
        co2Equivalent: fmt(flow.get('s_co2')),
        breathVocEquivalent: fmt(flow.get('s_voc')),

        rawTemperature: fmt(flow.get('s_rawT')),
        rawHumidity: fmt(flow.get('s_rawH')),

        gasResistance: fmt(flow.get('s_gas')),
        gasPercentage: fmt(flow.get('s_gasP')),

        // --- Enteros (Último estado registrado en la hora) ---
        iaqAccuracy: flow.get('last_acc'),
        stabStatus: flow.get('last_stab'),
        runInStatus: flow.get('last_run'),

        samples: count // Para debug
    };

    // --- RESETEAR TODO ---
    var keys = ['count', 's_temp', 's_hum', 's_press', 's_iaq', 's_static', 
                's_co2', 's_voc', 's_gas', 's_gasP', 's_rawT', 's_rawH'];

    // Ponemos todas las variables en 0 para la siguiente hora
    keys.forEach(k => flow.set(k, 0));

    return msg;
}

return null;
